changeSet.sql:
DO $do$
DECLARE
    actor CONSTANT TEXT := 'portal-workbench-root-bootstrap';
    workbench_root_count INTEGER;
    unsafe_candidate_count INTEGER;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('dts:portal-menu:workbench-root-bootstrap:20260901-01', 0));

    SELECT COUNT(*)
      INTO workbench_root_count
      FROM portal_menu
     WHERE parent_id IS NULL
       AND deleted = FALSE
       AND (
           name = 'sys.nav.portal.workbench'
           OR path = 'workbench'
           OR (
               metadata IS NOT NULL
               AND (
                   metadata::jsonb ->> 'key' = 'workbench'
                   OR metadata::jsonb ->> 'sectionKey' = 'workbench'
                   OR metadata::jsonb ->> 'titleKey' = 'sys.nav.portal.workbench'
               )
           )
       );

    IF workbench_root_count = 1 THEN
        RETURN;
    END IF;
    IF workbench_root_count > 1 THEN
        RAISE EXCEPTION 'portal workbench root is ambiguous before bootstrap: % active rows',
            workbench_root_count;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM portal_menu) THEN
        RETURN;
    END IF;

    SELECT COUNT(*)
      INTO unsafe_candidate_count
      FROM portal_menu
     WHERE name = 'sys.nav.portal.workbench'
        OR path = 'workbench'
        OR path LIKE 'workbench/%'
        OR (
            metadata IS NOT NULL
            AND (
                metadata::jsonb ->> 'key' = 'workbench'
                OR metadata::jsonb ->> 'sectionKey' = 'workbench'
                OR metadata::jsonb ->> 'titleKey' = 'sys.nav.portal.workbench'
            )
        );

    IF unsafe_candidate_count > 0 THEN
        RAISE EXCEPTION 'portal workbench root is missing but % workbench-like rows require manual reconciliation',
            unsafe_candidate_count;
    END IF;

    INSERT INTO portal_menu (
        name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted,
        created_by, created_date, last_modified_by, last_modified_date
    ) VALUES (
        'sys.nav.portal.workbench',
        'workbench',
        NULL,
        1,
        '{"key":"workbench","sectionKey":"workbench","titleKey":"sys.nav.portal.workbench","title":"工作台","icon":"solar:widget-3-bold-duotone"}',
        NULL,
        'solar:widget-3-bold-duotone',
        'GENERAL',
        FALSE,
        actor, now(), actor, now()
    );
END
$do$;

rollback.sql:
DO $do$
DECLARE
    actor CONSTANT TEXT := 'portal-workbench-root-bootstrap';
    workbench_id BIGINT;
    workbench_root_count INTEGER;
    descendant_count INTEGER;
    visibility_count INTEGER;
BEGIN
    SELECT COUNT(*), MIN(id)
      INTO workbench_root_count, workbench_id
      FROM portal_menu
     WHERE parent_id IS NULL
       AND created_by = actor
       AND metadata IS NOT NULL
       AND metadata::jsonb ->> 'key' = 'workbench';

    IF workbench_root_count = 0 THEN
        RETURN;
    END IF;
    IF workbench_root_count > 1 THEN
        RAISE EXCEPTION 'migration-owned portal workbench roots are ambiguous during bootstrap rollback: % rows',
            workbench_root_count;
    END IF;

    WITH RECURSIVE descendants AS (
        SELECT id
          FROM portal_menu
         WHERE parent_id = workbench_id
        UNION ALL
        SELECT child.id
          FROM portal_menu child
          JOIN descendants parent ON child.parent_id = parent.id
    )
    SELECT COUNT(*)
      INTO descendant_count
      FROM descendants;

    IF descendant_count > 0 THEN
        RAISE EXCEPTION 'portal workbench bootstrap rollback found % descendant rows', descendant_count;
    END IF;

    SELECT COUNT(*)
      INTO visibility_count
      FROM portal_menu_visibility
     WHERE menu_id = workbench_id;

    IF visibility_count > 0 THEN
        RAISE EXCEPTION 'portal workbench bootstrap rollback found % visibility rows', visibility_count;
    END IF;

    DELETE FROM portal_menu WHERE id = workbench_id AND created_by = actor;
END
$do$;
